import{_ as d,o as e,c as l,a6 as a}from"./chunks/framework.BBIckNDn.js";const g=JSON.parse('{"title":"ゲームプログラマのための完全理解教本","description":"","frontmatter":{"title":"ゲームプログラマのための完全理解教本","study":{"source":"IT教本","kind":"学習ガイド","status":"学習計画・概要","summary":"対象読者: ゲームプログラマ2年目。エンジンは使えるが、その下で何が起きているかを 「大学4年間 + ゲーム会社新人教育 + エンジン開発者育成」レベルで理解したい人。 下から上へ、ただしゲームに必要な最短経路で。"}},"headers":[],"relativePath":"guide/low-level/index.md","filePath":"guide/low-level/index.md"}'),r={name:"guide/low-level/index.md"};function i(o,t,n,h,s,u){return e(),l("div",null,[...t[0]||(t[0]=[a('<h1 id="ゲームプログラマのための完全理解教本" tabindex="-1">ゲームプログラマのための完全理解教本 <a class="header-anchor" href="#ゲームプログラマのための完全理解教本" aria-label="Permalink to &quot;ゲームプログラマのための完全理解教本&quot;">​</a></h1><h2 id="「パッドのボタンを押してから、画面にゲームが表示されるまで」をブラックボックスなしで理解する" tabindex="-1">「パッドのボタンを押してから、画面にゲームが表示されるまで」をブラックボックスなしで理解する <a class="header-anchor" href="#「パッドのボタンを押してから、画面にゲームが表示されるまで」をブラックボックスなしで理解する" aria-label="Permalink to &quot;「パッドのボタンを押してから、画面にゲームが表示されるまで」をブラックボックスなしで理解する&quot;">​</a></h2><p>対象読者: ゲームプログラマ2年目。エンジンは使えるが、その下で何が起きているかを 「大学4年間 + ゲーム会社新人教育 + エンジン開発者育成」レベルで理解したい人。</p><hr><h2 id="目次" tabindex="-1">目次 <a class="header-anchor" href="#目次" aria-label="Permalink to &quot;目次&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章</th><th>ファイル</th><th>テーマ</th></tr></thead><tbody><tr><td>第0章</td><td><a href="/study/guide/low-level/learning-map.html">00_学習全体マップ.md</a></td><td>全体像・学習戦略・環境構築</td></tr><tr><td>第1章</td><td><a href="/study/guide/low-level/computer-and-data.html">01_コンピュータとは何か.md</a></td><td>情報の表現・2進数・ノイマン型</td></tr><tr><td>第2章</td><td><a href="/study/guide/low-level/electricity-cpu-instructions.html">02_電気_CPU_命令.md</a></td><td>論理回路→CPU→命令セット</td></tr><tr><td>第3章</td><td><a href="/study/guide/low-level/memory-and-cache.html">03_メモリとキャッシュ.md</a></td><td>メモリ階層・キャッシュ・データ指向の土台</td></tr><tr><td>第4章</td><td><a href="/study/guide/low-level/assembly.html">04_アセンブリ.md</a></td><td>x64アセンブリ・VSで逆アセンブリを読む</td></tr><tr><td>第5章</td><td><a href="/study/guide/low-level/c-language.html">05_C言語.md</a></td><td>メモリと機械語への接続</td></tr><tr><td>第6章</td><td><a href="/study/guide/low-level/pointers-and-memory.html">06_ポインタとメモリ管理.md</a></td><td>ポインタ・記憶域・アロケータ</td></tr><tr><td>第7章</td><td><a href="/study/guide/low-level/compiler-linker-executable.html">07_コンパイラ_リンカ_実行ファイル.md</a></td><td>コンパイラ・リンカ・ELF/PE・ABI</td></tr><tr><td>第8章</td><td><a href="/study/guide/low-level/operating-system.html">08_OS.md</a></td><td>プロセス・スレッド・仮想メモリ・システムコール</td></tr><tr><td>第9章</td><td><a href="/study/guide/low-level/cpp-language.html">09_Cpp.md</a></td><td>C++ ── ゲーム業界の母語</td></tr><tr><td>第10章</td><td><a href="/study/guide/low-level/algorithms-and-game-math.html">10_データ構造_アルゴリズム_ゲーム数学.md</a></td><td>ゲームに効くDS/Algo・線形代数</td></tr><tr><td>第11章</td><td><a href="/study/guide/low-level/gpu-architecture.html">11_GPUアーキテクチャ.md</a></td><td>GPUはなぜ速いのか</td></tr><tr><td>第12章</td><td><a href="/study/guide/low-level/rendering-pipeline-shaders.html">12_レンダリングパイプラインとシェーダ.md</a></td><td>頂点からピクセルまで</td></tr><tr><td>第13章</td><td><a href="/study/guide/low-level/graphics-apis.html">13_グラフィックスAPI.md</a></td><td>OpenGL / DirectX 12 / Vulkan</td></tr><tr><td>第14章</td><td><a href="/study/guide/low-level/input-and-game-loop.html">14_入力とゲームループ.md</a></td><td>パッド入力の旅・時間・フレーム</td></tr><tr><td>第15章</td><td><a href="/study/guide/low-level/engine-architecture-ecs.html">15_ゲームエンジンアーキテクチャとECS.md</a></td><td>エンジンの解剖学・ECS</td></tr><tr><td>第16章</td><td><a href="/study/guide/low-level/unity-internals.html">16_Unityの内部.md</a></td><td>C#/IL2CPP/DOTS・内部実装を想像する</td></tr><tr><td>第17章</td><td><a href="/study/guide/low-level/unreal-internals.html">17_UnrealEngineの内部.md</a></td><td>UE5ソースコードリーディング</td></tr><tr><td>第18章</td><td><a href="/study/guide/low-level/debugging-and-profiling.html">18_デバッグとプロファイリング.md</a></td><td>VS・RenderDoc・PIX・Tracy</td></tr><tr><td>最終章</td><td><a href="/study/guide/low-level/button-to-screen.html">19_最終章_ボタンから画面まで.md</a></td><td>全章統合 ── 1フレームの完全な旅</td></tr><tr><td>発展章</td><td><a href="/study/guide/low-level/advanced-topics.html">20_発展編.md</a></td><td>トップレベルを目指す人向けトピック</td></tr></tbody></table><hr><h2 id="この教本の設計思想" tabindex="-1">この教本の設計思想 <a class="header-anchor" href="#この教本の設計思想" aria-label="Permalink to &quot;この教本の設計思想&quot;">​</a></h2><ol><li><p><strong>下から上へ、ただしゲームに必要な最短経路で。</strong> 電子回路の物理やチューリングマシンの証明のような「教養としては面白いが ゲーム開発に直結しない寄り道」は最小限にし、CPU・メモリ・OS・GPUという 「ゲームが実際に走る場所」に紙面を集中させる。</p></li><li><p><strong>すべての章が最終章(1フレームの旅)への伏線。</strong> 各章末の図で「今学んだことがフレームのどこで使われるか」を必ず示す。</p></li><li><p><strong>読む・書く・覗くの三本柱。</strong> 本を読むだけでは理解にならない。各章で必ず (a) コードを書き、 (b) OSSのソースを読み、(c) デバッガ/プロファイラで実物を覗く。</p></li></ol><hr><h2 id="このロードマップを完了した人は何ができるようになるか" tabindex="-1">このロードマップを完了した人は何ができるようになるか <a class="header-anchor" href="#このロードマップを完了した人は何ができるようになるか" aria-label="Permalink to &quot;このロードマップを完了した人は何ができるようになるか&quot;">​</a></h2><h3 id="具体的なスキル" tabindex="-1">具体的なスキル <a class="header-anchor" href="#具体的なスキル" aria-label="Permalink to &quot;具体的なスキル&quot;">​</a></h3><ul><li><strong>UE5のソースコードが読める</strong>: <code>FEngineLoop::Tick()</code> から <code>RHICmdList</code> 経由で D3D12/Vulkanのコマンド発行までコールスタックを追い、UObject/GC/リフレクションの 仕組みを説明できる。</li><li><strong>Unityの内部実装を想像できる</strong>: 「<code>GetComponent</code>はなぜ遅いか」「IL2CPPは C#をどうC++に変換するか」「DOTSはなぜ速いか」をメモリレイアウトと キャッシュの言葉で説明できる。</li><li><strong>RenderDocでGPUを追える</strong>: 1フレームをキャプチャして、ドローコール単位で 頂点入力→VS→ラスタライズ→PS→出力マージャを検査し、描画バグの原因 (ステート設定ミス、UV反転、深度テスト失敗など)を特定できる。</li><li><strong>Visual Studioでアセンブリまで追える</strong>: 逆アセンブリウィンドウでC++コードと 機械語の対応を読み、レジスタ・コールスタック・メモリウィンドウで クラッシュダンプの原因(ダングリングポインタ、スタック破壊等)を解析できる。</li><li><strong>ゲームエンジンを簡易実装できる</strong>: プラットフォーム層(ウィンドウ・入力)、 レンダラ(D3D12 or Vulkan or OpenGL)、リソース管理、ゲームループ、ECS、 簡易物理を備えた2D/3Dエンジンをゼロから書ける。</li><li><strong>AIが生成したコードをレビューできる</strong>: 「動くけど毎フレームヒープ確保している」 「このshared_ptrは循環参照する」「このループはキャッシュミスだらけ」といった、 表面的には正しいが性能・安全性に問題のあるコードを見抜ける。</li></ul><h3 id="思考レベルの変化" tabindex="-1">思考レベルの変化 <a class="header-anchor" href="#思考レベルの変化" aria-label="Permalink to &quot;思考レベルの変化&quot;">​</a></h3><ul><li>パフォーマンス問題を前に「なんとなく重い」ではなく 「CPUバウンドかGPUバウンドか → どのパスか → キャッシュか分岐かALUか」と 計測に基づいて系統的に切り分けられる。</li><li>クラッシュを前に「再起動して祈る」ではなく、ダンプとレジスタと メモリレイアウトから原因を論理的に特定できる。</li><li>新しいエンジン・API・言語に出会っても「下のレイヤは同じ」なので ドキュメントの行間が読め、習得が桁違いに速くなる。</li></ul><hr><h2 id="推奨学習ペース-目安" tabindex="-1">推奨学習ペース(目安) <a class="header-anchor" href="#推奨学習ペース-目安" aria-label="Permalink to &quot;推奨学習ペース(目安)&quot;">​</a></h2><p>働きながらの場合、<strong>全体で18〜30ヶ月</strong>を想定。焦らないこと。</p><ul><li>第1〜4章(ハードウェア・アセンブリ): 2〜3ヶ月</li><li>第5〜7章(C・ポインタ・コンパイラ/リンカ): 3〜4ヶ月</li><li>第8章(OS): 2〜3ヶ月</li><li>第9〜10章(C++・DS/Algo/数学): 3〜4ヶ月</li><li>第11〜13章(GPU・レンダリング・API): 3〜5ヶ月</li><li>第14〜15章(ゲームループ・エンジン/ECS): 2〜3ヶ月(自作エンジン開始)</li><li>第16〜18章(Unity/UE内部・デバッグ): 3〜4ヶ月</li><li>最終章・発展編: 継続的に</li></ul><p>「1章を100%理解してから次へ」ではなく、<strong>70%で先に進み、後の章で戻ってくる</strong> 螺旋型を推奨する。後の章が前の章の最高の復習になるよう設計してある。</p>',20)])])}const c=d(r,[["render",i]]);export{g as __pageData,c as default};
